import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { FlaskConical, Info } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  SIMULATED_MARKET_DISCLAIMER_AR,
  SIMULATED_MARKET_DISCLAIMER_EN,
  type DataProvenance,
} from "@/lib/dataProvenance";

/**
 * Banner for market/weather screens.
 *
 * Market prices in AgroGrowth are generated by a synthetic model because no
 * licensed live feed is configured. The server advertises this via the
 * `X-Data-Provenance` header, and this banner is what makes that visible to the
 * farmer -- without it the UI shows authoritative-looking TND figures that are
 * not real.
 */
export function MarketProvenanceNotice({
  provenance,
  className,
}: {
  provenance: DataProvenance;
  className?: string;
}) {
  if (!provenance.simulated) return null;

  const text = provenance.disclaimer || SIMULATED_MARKET_DISCLAIMER_AR;

  return (
    <Alert
      className={cn("border-amber-300 bg-amber-50 text-amber-900", className)}
      role="status"
    >
      <FlaskConical className="h-4 w-4" />
      <AlertTitle className="text-sm font-semibold">
        بيانات محاكاة — ليست أسعاراً حقيقية
      </AlertTitle>
      <AlertDescription className="text-sm">
        {text}
        <span className="mt-1 block text-xs opacity-80" dir="ltr">
          {SIMULATED_MARKET_DISCLAIMER_EN}
        </span>
      </AlertDescription>
    </Alert>
  );
}

/** Neutral notice for payloads whose source the server did not declare. */
export function UnknownProvenanceNotice({ className }: { className?: string }) {
  return (
    <Alert
      className={cn("border-slate-300 bg-slate-50", className)}
      role="status"
    >
      <Info className="h-4 w-4" />
      <AlertDescription className="text-sm text-slate-800">
        لم يُعلن مصدر هذه البيانات. تعامل معها بحذر.
      </AlertDescription>
    </Alert>
  );
}
